<?php requireAdmin(); $modules=db()->query('SELECT * FROM modules ORDER BY module_key')->fetchAll(); ?>
<div class="panel"><h2>Modulverwaltung</h2><div class="notice">Modulpfade sind nur relativ innerhalb <strong>/modules/</strong> erlaubt. Pfadmanipulation mit absoluten Pfaden oder „..“ wird blockiert.</div>
<form class="ajax-form form-grid" action="ajax/admin_modules.php" data-reload="admin_modules" method="post"><?= csrfField() ?><input type="hidden" name="id" value="0"><label>Modul-Key<input name="module_key" required></label><label>Titel<input name="title" required></label><label>Pfad unter modules/<input name="module_path" placeholder="dashboard/index.php" required></label><label><input type="checkbox" name="is_active" checked> aktiv</label><div><button>Modul anlegen</button></div></form></div>
<div class="panel"><table class="data-table js-data-table"><thead><tr><th>Key</th><th>Titel</th><th>Pfad</th><th>Status</th></tr></thead><tbody><?php foreach($modules as $m): ?><tr><td><?= e($m['module_key']) ?></td><td><?= e($m['title']) ?></td><td><?= e($m['module_path']) ?></td><td><?= statusBadge((int)$m['is_active']?'aktiv':'inaktiv') ?></td></tr><?php endforeach; ?></tbody></table></div><script>initDataTable('.js-data-table');</script>
